#include <vector>
#include <cstddef>
#include <cmath>
#include <algorithm>
#include <omp.h>

struct COOElement {
   size_t row, column;
   double value;
};

/* Solve the sparse linear system Ax=b for x.
   A is a sparse NxN matrix in COO format. x and b are dense vectors with N elements.
   Uses a parallel Jacobi iterative method with OpenMP.
*/
void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {
    x.assign(N, 0.0);
    if (N == 0) return;

    // Build CSR from COO (single-threaded preprocessing for determinism/safety)
    std::vector<size_t> rowCounts(N, 0);
    for (const auto& e : A) {
        if (e.row < N && e.column < N) {
            rowCounts[e.row]++;
        }
    }

    std::vector<size_t> rowPtr(N + 1, 0);
    for (size_t i = 0; i < N; ++i) rowPtr[i + 1] = rowPtr[i] + rowCounts[i];

    const size_t nnz = rowPtr[N];
    std::vector<size_t> colIdx(nnz);
    std::vector<double> values(nnz);
    std::vector<size_t> fillPos = rowPtr;

    for (const auto& e : A) {
        if (e.row < N && e.column < N) {
            size_t p = fillPos[e.row]++;
            colIdx[p] = e.column;
            values[p] = e.value;
        }
    }

    std::vector<double> xNew(N, 0.0);
    std::vector<double> diag(N, 0.0);

    // Extract diagonal entries (sum if duplicates exist)
    #pragma omp parallel for schedule(static)
    for (size_t i = 0; i < N; ++i) {
        double d = 0.0;
        for (size_t p = rowPtr[i]; p < rowPtr[i + 1]; ++p) {
            if (colIdx[p] == i) d += values[p];
        }
        diag[i] = d;
    }

    // Jacobi iteration parameters
    const size_t maxIters = 10000;
    const double tol = 1e-10;

    for (size_t iter = 0; iter < maxIters; ++iter) {
        double maxDiff = 0.0;

        #pragma omp parallel for reduction(max:maxDiff) schedule(static)
        for (size_t i = 0; i < N; ++i) {
            if (i >= b.size()) {
                xNew[i] = x[i];
                continue;
            }

            double d = diag[i];
            if (std::abs(d) < 1e-20) {
                // No usable diagonal => keep previous value
                xNew[i] = x[i];
            } else {
                double sum = 0.0;
                for (size_t p = rowPtr[i]; p < rowPtr[i + 1]; ++p) {
                    size_t j = colIdx[p];
                    if (j != i && j < N) sum += values[p] * x[j];
                }
                xNew[i] = (b[i] - sum) / d;
            }

            double diff = std::abs(xNew[i] - x[i]);
            if (diff > maxDiff) maxDiff = diff;
        }

        x.swap(xNew);
        if (maxDiff < tol) break;
    }
}
